// Plain waypoint follower: position PD, slow altitude integral, no trial recognition.
export default function makeController() {
  let targetIndex = -1, phase = 'climb', integralY = 0, settle = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  return {
    step(obs) {
      const p = obs.pos, v = obs.vel;
      let target;
      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) { targetIndex = obs.gateIndex; phase = 'align'; settle = 0; }
        if (phase === 'align') {
          target = { x: gate.x - 0.45, y: gate.y, z: gate.z };
          if (Math.hypot(target.x - p.x, target.y - p.y, target.z - p.z) < 0.10 && Math.hypot(v.x, v.y, v.z) < 0.35) settle++;
          else settle = 0;
          if (settle > 15) phase = 'cross';
        }
        if (phase === 'cross') target = { x: gate.x + 0.35, y: gate.y, z: gate.z };
      } else {
        target = { x: obs.pad.centre.x, y: 0.95, z: obs.pad.centre.z };
        if (phase !== 'descend' && Math.hypot(target.x - p.x, target.z - p.z) < 0.09 && Math.hypot(v.x, v.z) < 0.20) phase = 'descend';
        if (phase === 'descend') target.y = 0.025;
      }
      const ax = clamp(3.8 * (target.x - p.x) - 3.2 * v.x, -2.8, 2.8);
      const az = clamp(3.8 * (target.z - p.z) - 3.2 * v.z, -2.8, 2.8);
      const ey = target.y - p.y;
      integralY = clamp(integralY + ey * 0.01, -0.5, 1.9);
      const ay = clamp(5.5 * ey - 3.5 * v.y + 2.4 * integralY, -3.5, 4.5);
      const cy = Math.cos(obs.att.yaw), sy = Math.sin(obs.att.yaw);
      const pitch = clamp((cy * ax - sy * az) / 9.81, -0.45, 0.45);
      const roll = clamp(-(sy * ax + cy * az) / 9.81, -0.45, 0.45);
      const thrust = (0.72 * (9.81 + ay)) / (16 * Math.max(0.7, Math.cos(obs.att.roll) * Math.cos(obs.att.pitch)));
      return { thrust, roll, pitch, yawRate: -2 * obs.att.yaw };
    },
  };
}

// Trusted simulation. No controller source is imported or executed in this process.
import { spawn } from 'node:child_process';
import { readFileSync, realpathSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { TASK, TAKEOFF, GATES, PAD, random, trialParameters } from './task.mjs';

const FORBIDDEN = /import|require|process|globalThis|constructor|prototype|__proto__|eval|Function|Reflect|Proxy|fetch|Date|performance/;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const norm = (v) => Math.hypot(v.x, v.y, v.z);
// Node 26 has --permission (and restricts the network too); Google's Managed Agents sandboxes run Node 22, which has
// --experimental-permission (files, child processes and workers restricted; network not). The child holds no secret.
const PERM = process.allowedNodeEnvironmentFlags.has('--permission') ? '--permission'
  : process.allowedNodeEnvironmentFlags.has('--experimental-permission') ? '--experimental-permission' : null;
const copy = (v) => ({ ...v });
const MOTOR_X = [-1, 1, 1, -1], MOTOR_Z = [-1, -1, 1, 1], SPIN = [1, -1, 1, -1];

export function validateSource(path) {
  if (!PERM) throw new Error('this task requires Node with the permission model (Node 22 or later)');
  const absolute = realpathSync(path);
  if (!statSync(absolute).isFile()) throw new Error('controller must be a file');
  const source = readFileSync(absolute, 'utf8');
  if (Buffer.byteLength(source) > 256 * 1024) throw new Error('controller exceeds 256 KiB source limit');
  const token = source.match(FORBIDDEN)?.[0];
  if (token) throw new Error(`forbidden source token: ${token}`);
  return absolute;
}

class ControllerProcess {
  constructor(artifact) {
    const host = fileURLToPath(new URL('./host.mjs', import.meta.url));
    this.child = spawn(process.execPath, [PERM, `--allow-fs-read=${host}`, `--allow-fs-read=${artifact}`, '--max-old-space-size=48', host, artifact], {
      env: {}, stdio: ['pipe', 'pipe', 'pipe'], cwd: '/',
    });
    this.buffer = ''; this.stderr = ''; this.pending = null; this.dead = null;
    this.child.stderr.on('data', (chunk) => { this.stderr = (this.stderr + chunk).slice(-1200); });
    this.child.stdout.on('data', (chunk) => {
      this.buffer += chunk;
      if (this.buffer.length > 16384) return this.fail(new Error('controller output exceeds protocol limit'));
      let end;
      while ((end = this.buffer.indexOf('\n')) >= 0) {
        const line = this.buffer.slice(0, end); this.buffer = this.buffer.slice(end + 1);
        if (!this.pending) return this.fail(new Error('unsolicited controller output'));
        const pending = this.pending; this.pending = null; clearTimeout(pending.timer);
        try { pending.resolve(JSON.parse(line)); }
        catch { pending.reject(new Error('malformed controller JSON')); }
      }
    });
    this.child.on('error', (error) => this.fail(error));
    this.child.on('exit', (code, signal) => this.fail(new Error(`controller exited (${signal || code})${this.stderr ? ': ' + this.stderr.slice(-180) : ''}`)));
    this.child.stdin.on('error', (error) => this.fail(error));
  }
  fail(error) {
    this.dead ||= error;
    if (this.pending) {
      clearTimeout(this.pending.timer); this.pending.reject(this.dead); this.pending = null;
    }
    this.child.kill('SIGKILL');
  }
  message(timeout, obs) {
    if (this.dead) return Promise.reject(this.dead);
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => this.fail(new Error(obs ? 'controller step exceeded 50 ms' : 'controller startup exceeded 3000 ms')), timeout);
      this.pending = { resolve, reject, timer };
      if (obs) this.child.stdin.write(JSON.stringify({ obs }) + '\n');
    });
  }
  async ready() {
    const message = await this.message(3000);
    if (message.ready !== true) throw new Error('controller did not send ready');
  }
  async step(obs) {
    const response = await this.message(50, obs);
    if (response.error) throw new Error(`controller error: ${response.error}`);
    const action = response.action;
    if (!action || typeof action !== 'object' || Array.isArray(action) ||
      !['thrust', 'roll', 'pitch', 'yawRate'].every((k) => typeof action[k] === 'number' && Number.isFinite(action[k]))) {
      throw new Error('malformed action: four finite numbers required');
    }
    return { thrust: clamp(action.thrust, 0, 1), roll: clamp(action.roll, -0.6, 0.6),
      pitch: clamp(action.pitch, -0.6, 0.6), yawRate: clamp(action.yawRate, -2, 2) };
  }
  close() { this.child.kill('SIGKILL'); }
}

export function initialState(parameters) {
  return {
    t: 0, pos: { x: TAKEOFF.x + parameters.offset.x, y: TASK.bodyHeight, z: TAKEOFF.z + parameters.offset.z },
    vel: { x: 0, y: 0, z: 0 }, att: { roll: 0, pitch: 0, yaw: 0 },
    rates: { roll: 0, pitch: 0, yaw: 0 }, motors: [0, 0, 0, 0], integral: { roll: 0, pitch: 0 },
    gateIndex: 0, landedFor: 0, airborne: false, reason: null,
  };
}

function observation(state, rng) {
  const noise = (n) => (rng() + rng() + rng() - 1.5) * n;
  const vector = (v, n) => Object.fromEntries(Object.entries(v).map(([key, value]) => [key, value + noise(n)]));
  return {
    t: +state.t.toFixed(4), pos: vector(state.pos, TASK.positionNoise), vel: vector(state.vel, TASK.velocityNoise),
    att: vector(state.att, TASK.attitudeNoise), rates: vector(state.rates, TASK.rateNoise),
    gateIndex: state.gateIndex,
    nextGate: state.gateIndex < GATES.length ? { centre: copy(GATES[state.gateIndex].centre), normal: copy(GATES[state.gateIndex].normal) } : null,
    pad: { centre: copy(PAD.centre) },
  };
}

function integrate(state, action, parameters, dt) {
  const old = copy(state.pos), { att, rates } = state;
  const inertia = TASK.inertia * parameters.mass / TASK.baseMass;
  const torque = {};
  for (const axis of ['roll', 'pitch']) {
    const error = action[axis] - att[axis];
    state.integral[axis] = clamp(state.integral[axis] + error * dt, -0.35, 0.35);
    torque[axis] = inertia * (65 * error - 13 * rates[axis] + 22 * state.integral[axis]);
  }
  torque.yaw = inertia * 8 * (action.yawRate - rates.yaw);
  for (let i = 0; i < 4; i++) {
    const desired = action.thrust * TASK.maxMotorThrust +
      torque.roll * MOTOR_Z[i] / (4 * TASK.arm) - torque.pitch * MOTOR_X[i] / (4 * TASK.arm) +
      torque.yaw * SPIN[i] / (4 * TASK.yawCoefficient);
    const target = clamp(desired, 0, TASK.maxMotorThrust) * (i === parameters.weakMotor ? 1 - parameters.weakness : 1);
    state.motors[i] += (target - state.motors[i]) * (1 - Math.exp(-dt / parameters.lag));
  }
  const sum = state.motors.reduce((a, b) => a + b, 0);
  const moment = (sign) => state.motors.reduce((a, f, i) => a + f * sign[i], 0);
  rates.roll += (TASK.arm * moment(MOTOR_Z) / inertia - 0.4 * rates.roll) * dt;
  rates.pitch += (-TASK.arm * moment(MOTOR_X) / inertia - 0.4 * rates.pitch) * dt;
  rates.yaw += (TASK.yawCoefficient * moment(SPIN) / inertia - 0.4 * rates.yaw) * dt;
  for (const axis of ['roll', 'pitch', 'yaw']) att[axis] += rates[axis] * dt;
  const bodyX = Math.sin(att.pitch) * Math.cos(att.roll), bodyZ = -Math.sin(att.roll);
  const direction = { x: Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ,
    y: Math.cos(att.pitch) * Math.cos(att.roll), z: -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ };
  const wind = copy(parameters.baseWind);
  for (const gust of parameters.gusts) if (state.t >= gust.start && state.t < gust.start + gust.duration) {
    wind.x += gust.x; wind.y += gust.y; wind.z += gust.z;
  }
  for (const axis of ['x', 'y', 'z']) {
    const force = sum * direction[axis] + TASK.linearDrag * (wind[axis] - state.vel[axis]);
    state.vel[axis] += (force / parameters.mass - (axis === 'y' ? TASK.gravity : 0)) * dt;
    state.pos[axis] += state.vel[axis] * dt;
  }
  state.t += dt;
  if (state.pos.y > TASK.bodyHeight + 0.08) state.airborne = true;
  if (Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > TASK.flipAngle) state.reason = 'flipped';
  if (Math.abs(state.pos.x) + TASK.bodyRadius >= TASK.room.maxX || Math.abs(state.pos.z) + TASK.bodyRadius >= TASK.room.maxZ || state.pos.y + TASK.bodyHeight >= TASK.room.height) {
    if (norm(state.vel) > TASK.contactCrashSpeed) state.reason = 'wall or ceiling crash';
    state.pos.x = clamp(state.pos.x, TASK.room.minX + TASK.bodyRadius, TASK.room.maxX - TASK.bodyRadius);
    state.pos.z = clamp(state.pos.z, TASK.room.minZ + TASK.bodyRadius, TASK.room.maxZ - TASK.bodyRadius);
    state.pos.y = Math.min(state.pos.y, TASK.room.height - TASK.bodyHeight);
    state.vel.x = 0; state.vel.z = 0; state.vel.y = Math.min(state.vel.y, 0);
  }
  if (state.pos.y <= TASK.bodyHeight) {
    if (state.airborne && (norm(state.vel) > TASK.contactCrashSpeed || Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > TASK.landingTilt * 2)) state.reason = 'floor crash';
    state.pos.y = TASK.bodyHeight; state.vel.y = Math.max(0, state.vel.y);
    state.vel.x *= Math.exp(-12 * dt); state.vel.z *= Math.exp(-12 * dt);
  }
  // Sweep the entire body through each gate plane, rather than testing the centre only.
  for (let i = 0; i < GATES.length; i++) {
    const gate = GATES[i], x = gate.centre.x;
    if ((old.x < x && state.pos.x >= x) || (old.x > x && state.pos.x <= x)) {
      const fraction = (x - old.x) / (state.pos.x - old.x);
      const y = old.y + fraction * (state.pos.y - old.y), z = old.z + fraction * (state.pos.z - old.z);
      const dy = Math.abs(y - gate.centre.y), dz = Math.abs(z - gate.centre.z);
      const half = TASK.gateOpening / 2, outer = half + TASK.gateFrame;
      const fits = dy + TASK.bodyHeight <= half && dz + TASK.bodyRadius <= half;
      const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
      if (overlapsFrame) state.reason = 'gate frame collision';
      if (i === state.gateIndex && old.x < x && state.pos.x >= x && fits) state.gateIndex++;
    }
  }
  const error = Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z);
  if (state.gateIndex === GATES.length && error <= TASK.landingRadius && state.pos.y <= TASK.bodyHeight + 0.025 &&
      norm(state.vel) < TASK.landingSpeed && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < TASK.landingTilt) state.landedFor += dt;
  else state.landedFor = 0;
  if (state.landedFor >= TASK.landingHold && !state.reason) state.reason = 'landed';
}

const frame = (s) => ({ t: +s.t.toFixed(4), pos: copy(s.pos), att: copy(s.att), gateIndex: s.gateIndex });

export async function runTrial(artifact, seed, { record = false } = {}) {
  const parameters = trialParameters(seed), state = initialState(parameters), rng = random((seed ^ 0xa5a5a5a5) >>> 0);
  const controller = new ControllerProcess(artifact);
  const frames = record ? [frame(state)] : undefined;
  let nextFrame = 1 / 30;
  try {
    await controller.ready();
    for (let step = 0; step < Math.round(TASK.duration / TASK.dt) && !state.reason; step++) {
      const action = await controller.step(observation(state, rng));
      const previous = record ? frame(state) : null;
      for (let sub = 0; sub < TASK.substeps && !state.reason; sub++) integrate(state, action, parameters, TASK.dt / TASK.substeps);
      if (record && state.t + 1e-8 >= nextFrame) {
        const u = clamp((nextFrame - previous.t) / (state.t - previous.t), 0, 1);
        const interpolate = (a, b) => Object.fromEntries(Object.keys(a).map((axis) => [axis, a[axis] + u * (b[axis] - a[axis])]));
        frames.push({ t: +nextFrame.toFixed(4), pos: interpolate(previous.pos, state.pos), att: interpolate(previous.att, state.att),
          gateIndex: u < 1 ? previous.gateIndex : state.gateIndex });
        nextFrame += 1 / 30;
      }
    }
  } catch (error) { state.reason = error.message; }
  finally { controller.close(); }
  if (record && frames.at(-1).t !== +state.t.toFixed(4)) frames.push(frame(state));
  const result = {
    seed, success: state.reason === 'landed', reason: state.reason || 'time limit', gatesPassed: state.gateIndex,
    landingError: +Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z).toFixed(4),
    simulatedSeconds: +state.t.toFixed(3),
  };
  return { result, track: record ? { version: TASK.version, fps: 30, seed, result, frames } : undefined };
}

#!/usr/bin/env node
import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { SPLITS } from './task.mjs';
import { validateSource, runTrial } from './sim.mjs';

const args = process.argv.slice(2), file = args[0];
const option = (name, fallback) => { const index = args.indexOf(name); return index >= 0 ? args[index + 1] : fallback; };
let split = option('--split', 'val'), seeds, output;
const start = performance.now();
try {
  if (!file || file.startsWith('--')) throw new Error('usage: node tasks/drone/run.mjs <controller.js> --split val|smoke [--json out.json] [--record dir]');
  if ([args.includes('--split'), args.includes('--seeds'), args.includes('--seeds-stdin')].filter(Boolean).length > 1) throw new Error('choose only one seed input: --split, --seeds, or --seeds-stdin');
  if (args.includes('--seeds-stdin')) { split = 'stdin'; seeds = JSON.parse(readFileSync(0, 'utf8')); }
  else if (option('--seeds')) { split = 'custom'; seeds = option('--seeds').split(',').map(Number); }
  else seeds = SPLITS[split];
  if (!Array.isArray(seeds) || !seeds.length || seeds.length > 4096 || !seeds.every((s) => Number.isInteger(s) && s >= 0 && s <= 0xffffffff)) throw new Error('expected a nonempty array of unsigned 32-bit seeds, or a known split');
  const artifact = validateSource(resolve(file)), results = [], recordDir = option('--record');
  if (args.includes('--record') && (!recordDir || recordDir.startsWith('--'))) throw new Error('--record requires a directory');
  if (recordDir) mkdirSync(recordDir, { recursive: true });
  for (const seed of seeds) {
    const { result, track } = await runTrial(artifact, seed, { record: Boolean(recordDir) });
    results.push(result);
    if (recordDir) writeFileSync(join(recordDir, `seed-${seed}.json`), JSON.stringify(track));
  }
  const passed = results.filter((r) => r.success).length;
  output = { scene: file, split, valid: true, passed, total: seeds.length, rate: passed / seeds.length, results };
} catch (error) {
  output = { scene: file || null, split, valid: false, error: error.message, passed: 0, total: seeds?.length || 0, rate: 0, results: [] };
}
output.seconds = +((performance.now() - start) / 1000).toFixed(3);
if (option('--json')) writeFileSync(option('--json'), JSON.stringify(output, null, 2));
if (!output.valid) { console.error(`INVALID CONTROLLER: ${output.error}`); process.exitCode = 1; }
else {
  console.log(`${split}: ${output.passed}/${output.total} trials landed (${output.seconds}s)`);
  for (const r of output.results) console.log(`  seed ${r.seed}: ${r.success ? 'PASS' : 'FAIL'}; ${r.reason}; gates ${r.gatesPassed}/3; pad error ${r.landingError} m; ${r.simulatedSeconds}s simulated`);
}

import * as THREE from '../../harness/node_modules/three/build/three.module.js';
import { TASK, GATES, TAKEOFF, PAD } from './task.mjs';

export function flightScene(label = () => {}) {
const scene = new THREE.Scene(); scene.background = new THREE.Color('#f3f1ec');
scene.add(new THREE.HemisphereLight('#ffffff', '#c5bda9', 2.4));
const sun = new THREE.DirectionalLight('#fff9e8', 3.0); sun.position.set(-3, 8, 3); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048); sun.shadow.camera.left = -6; sun.shadow.camera.right = 6;
sun.shadow.camera.top = 6; sun.shadow.camera.bottom = -6; sun.shadow.normalBias = 0.015;
scene.add(sun);
const material = (color, other = {}) => new THREE.MeshStandardMaterial({ color, roughness: 0.75, ...other });
const floorMat = material('#e7e6dc'), frameMat = material('#d39a4f'), padMat = material('#72b7a3');
function box(size, pos, mat, parent = scene) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), mat);
  mesh.position.set(...pos); mesh.castShadow = true; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
box([6.05, 0.07, 6.05], [0, -0.045, 0], floorMat);
const grid = new THREE.GridHelper(6, 12, '#c4c9bd', '#d1d5c9'); grid.position.y = 0.002; scene.add(grid);
const wallMat = material('#dde3da', { transparent: true, opacity: 0.24, depthWrite: false, side: THREE.DoubleSide });
box([0.025, 3, 6], [-3.02, 1.5, 0], wallMat); box([6, 3, 0.025], [0, 1.5, -3.02], wallMat);
const boundaryMat = new THREE.LineBasicMaterial({ color: '#acb8aa', transparent: true, opacity: 0.6 });
const edge = new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(6, 3, 6)), boundaryMat);
edge.position.y = 1.5; scene.add(edge);


for (let i = 0; i < GATES.length; i++) {
  const { x, y, z } = GATES[i].centre, h = TASK.gateOpening / 2, f = TASK.gateFrame;
  box([0.065, f, 2 * h + 2 * f], [x, y + h + f / 2, z], frameMat);
  box([0.065, f, 2 * h + 2 * f], [x, y - h - f / 2, z], frameMat);
  for (const sign of [-1, 1]) {
    box([0.065, 2 * h, f], [x, y, z + sign * (h + f / 2)], frameMat);
    box([0.035, Math.max(0.01, y - h - f), 0.035], [x, (y - h - f) / 2, z + sign * (h + f / 2)], material('#b7b7a3'));
  }
  label('GATE ' + (i + 1), [x, y + h + 0.26, z], '#8b632e', 0.65);
}
function pad(pos, text) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.28, 0.015, 48), padMat);
  mesh.position.set(pos.x, 0.012, pos.z); mesh.receiveShadow = true; scene.add(mesh);
  const ring = new THREE.Mesh(new THREE.RingGeometry(0.14, 0.153, 64), new THREE.MeshBasicMaterial({ color: '#f7fbf0', side: THREE.DoubleSide }));
  ring.rotation.x = -Math.PI / 2; ring.position.set(pos.x, 0.022, pos.z); scene.add(ring);
  label(text, [pos.x, 0.20, pos.z + 0.46], '#417365', 0.65);
}
pad(TAKEOFF, 'TAKE-OFF'); pad(PAD.centre, 'LAND');
const drone = new THREE.Group(); scene.add(drone);
box([0.13, 0.065, 0.10], [0, 0, 0], material('#f7faf4'), drone);
box([0.055, 0.018, 0.055], [0, 0.045, 0], material('#d08c49'), drone);
box([0.27, 0.018, 0.025], [0, 0.0, 0], material('#596c65'), drone);
box([0.025, 0.018, 0.27], [0, 0.0, 0], material('#596c65'), drone);
const rotors = [];
for (const x of [-TASK.arm, TASK.arm]) for (const z of [-TASK.arm, TASK.arm]) {
  const arm = box([Math.hypot(x, z), 0.016, 0.017], [x / 2, 0, z / 2], material('#71867b'), drone);
  arm.rotation.y = -Math.atan2(z, x);
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.024, 0.024, 0.035, 12), material('#789382'));
  hub.position.set(x, 0.022, z); drone.add(hub);
  const rotor = new THREE.Mesh(new THREE.CylinderGeometry(0.056, 0.056, 0.003, 32), material('#8fa99a', { transparent: true, opacity: 0.6 }));
  rotor.position.set(x, 0.044, z); drone.add(rotor); rotors.push(rotor);
}
for (const z of [-0.055, 0.055]) box([0.15, 0.012, 0.012], [0, -0.047, z], material('#596c65'), drone);

return { scene, drone };
}

export function setFlightCamera(camera, name, drone) {
  if (name === 'overview') { camera.position.set(6.8, 5.8, -7.8); camera.lookAt(0, 0.7, 0); }
  else if (name === 'low') { camera.position.set(6, 1.55, 5.5); camera.lookAt(0, 1, 0); }
  else if (name === 'top') { camera.position.set(0.05, 10.3, 0.05); camera.lookAt(0, 0, 0); }
  else if (name === 'chase') { camera.position.copy(drone.position).add(new THREE.Vector3(-2.8, 1.8, 2.8)); camera.lookAt(drone.position.clone().add(new THREE.Vector3(0.45, 0, 0))); }
  else {
    const values = name.split(',').map(Number);
    if (values.length !== 3 || !values.every(Number.isFinite) || values[2] <= 0) throw new Error('camera must be overview, chase, low, top, or azimuth,elevation,distance');
    const [az, el, distance] = values, a = az * Math.PI / 180, e = el * Math.PI / 180;
    camera.position.set(distance * Math.cos(e) * Math.cos(a), 0.9 + distance * Math.sin(e), distance * Math.cos(e) * Math.sin(a)); camera.lookAt(0, 0.9, 0);
  }
}

// Frozen benchmark definition. Change difficulty only before explorer/model runs.
export const TASK = Object.freeze({
  version: 'drone-hard-1', dt: 0.01, substeps: 2, duration: 15, gravity: 9.81,
  room: Object.freeze({ minX: -3, maxX: 3, minZ: -3, maxZ: 3, height: 3 }),
  baseMass: 0.6, payloadMax: 0.35, maxMotorThrust: 4.0,
  motorLagMin: 0.02, motorLagMax: 0.06, motorWeaknessMax: 0.35,
  arm: 0.115, inertia: 0.006, yawCoefficient: 0.014, linearDrag: 0.42,
  bodyRadius: 0.175, bodyHeight: 0.07, gateOpening: 0.42, gateFrame: 0.07,
  baseWindMax: 2.2, gustMin: 4, gustMax: 9, gustDurationMin: 0.2,
  gustDurationMax: 2.0, gustStartMin: 2.0, gustStartMax: 12.0,
  positionNoise: 0.001, velocityNoise: 0.018, attitudeNoise: 0.003,
  rateNoise: 0.012, startOffset: 0.045,
  contactCrashSpeed: 0.85, flipAngle: 1.2, landingRadius: 0.15,
  landingSpeed: 0.5, landingTilt: 0.18, landingHold: 0.25,
});

const v = (x, y, z) => Object.freeze({ x, y, z });
export const TAKEOFF = v(-2.1, 0, -1.65);
export const PAD = Object.freeze({ centre: v(2.05, 0, 1.65) });
export const GATES = Object.freeze([
  Object.freeze({ centre: v(-1.15, 1.05, -0.85), normal: v(1, 0, 0) }),
  Object.freeze({ centre: v(0.15, 1.40, 0.25), normal: v(1, 0, 0) }),
  Object.freeze({ centre: v(1.35, 1.05, 1.05), normal: v(1, 0, 0) }),
]);

export const SPLITS = {
  smoke: [101, 102, 103, 104],
};

export function random(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function trialParameters(seed) {
  const r = random(seed), between = (a, b) => a + (b - a) * r();
  const offset = { x: between(-TASK.startOffset, TASK.startOffset), z: between(-TASK.startOffset, TASK.startOffset) };
  const mass = TASK.baseMass + between(0, TASK.payloadMax);
  const lag = between(TASK.motorLagMin, TASK.motorLagMax);
  const weakMotor = Math.floor(r() * 4), weakness = between(0, TASK.motorWeaknessMax);
  const angle = between(0, 2 * Math.PI), strength = between(0, TASK.baseWindMax);
  const baseWind = { x: Math.cos(angle) * strength, y: 0, z: Math.sin(angle) * strength };
  const gusts = Array.from({ length: r() < 0.5 ? 2 : 3 }, (_, i) => {
    const start = between(TASK.gustStartMin, TASK.gustStartMax);
    // Every trial has one abrupt 200 ms gust, shorter than the navigation response.
    const duration = i === 0 ? TASK.gustDurationMin : between(TASK.gustDurationMin, TASK.gustDurationMax);
    const a = between(0, 2 * Math.PI), s = between(TASK.gustMin, TASK.gustMax);
    return { start, duration, x: Math.cos(a) * s, y: 0, z: Math.sin(a) * s };
  });
  return { offset, mass, lag, weakMotor, weakness, baseWind, gusts };
}

// Untrusted controller host. The parent grants only this file and the artifact read access.
import { readFileSync, readSync, writeSync } from 'node:fs';

const FORBIDDEN = /import|require|process|globalThis|constructor|prototype|__proto__|eval|Function|Reflect|Proxy|fetch|Date|performance/;
const source = readFileSync(process.argv[2], 'utf8');
if (FORBIDDEN.test(source)) throw new Error('forbidden source token');
const module = await import('data:text/javascript;base64,' + Buffer.from(source).toString('base64'));
if (typeof module.default !== 'function') throw new Error('expected default controller factory');
const controller = module.default();
if (!controller || typeof controller.step !== 'function') throw new Error('expected step(obs)');
// Raw stdio also works where creating Node net.Socket wrappers for child pipes is denied.
const send = (message) => writeSync(1, JSON.stringify(message) + '\n');
send({ ready: true });
const chunk = Buffer.alloc(8192);
let buffer = '', done = false;
while (!done) {
  const count = readSync(0, chunk, 0, chunk.length, null);
  if (!count) break;
  buffer += chunk.toString('utf8', 0, count);
  let end;
  while ((end = buffer.indexOf('\n')) >= 0) {
    const line = buffer.slice(0, end); buffer = buffer.slice(end + 1);
  try {
    const request = JSON.parse(line);
    const action = controller.step(request.obs);
    send({ action });
  } catch (error) {
    send({ error: String(error.message).slice(0, 180) });
    done = true;
    break;
  }
  }
}

