export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  let initialized = false;
  let px = 0, py = 0.07, pz = 0;
  let vx = 0, vy = 0, vz = 0;
  let dwx = 0, dwz = 0, dwy = 0;
  let kyEst = 16 / 0.78; // 16 * (1 - w/4) / m
  let mEst = 0.78;
  let rollTrim = 0, pitchTrim = 0, yawTrim = 0;
  let thrustFilt = 0.48;

  let gateIdx = -1;
  let phase = 'align';
  let settleCount = 0;
  let maxXReached = -3;

  return {
    step(obs) {
      const dt = 0.01;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (!initialized) {
        initialized = true;
        px = p.x; py = p.y; pz = p.z;
        vx = 0; vy = 0; vz = 0;
      } else {
        // Current thrust direction from attitude
        const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
        const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
        const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
        const bodyX = sp * cr, bodyZ = -sr;
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = cp * cr;
        const dirZ = -sy * bodyX + cy * bodyZ;

        const tSpec = kyEst * thrustFilt;
        const drag = 0.42 / mEst;

        const axKnown = tSpec * dirX - drag * vx;
        const ayKnown = tSpec * dirY - drag * vy - 9.81;
        const azKnown = tSpec * dirZ - drag * vz;

        const pxPred = px + vx * dt + 0.5 * (axKnown + dwx) * dt * dt;
        const pyPred = py + vy * dt + 0.5 * (ayKnown + dwy) * dt * dt;
        const pzPred = pz + vz * dt + 0.5 * (azKnown + dwz) * dt * dt;

        const vxPred = vx + (axKnown + dwx) * dt;
        const vyPred = vy + (ayKnown + dwy) * dt;
        const vzPred = vz + (azKnown + dwz) * dt;

        const epX = p.x - pxPred, epY = p.y - pyPred, epZ = p.z - pzPred;
        const evX = v.x - vxPred, evY = v.y - vyPred, evZ = v.z - vzPred;

        px = pxPred + 0.65 * epX;
        py = pyPred + 0.65 * epY;
        pz = pzPred + 0.65 * epZ;

        vx = vxPred + 0.50 * evX + 0.12 * (epX / dt);
        vy = vyPred + 0.50 * evY + 0.12 * (epY / dt);
        vz = vzPred + 0.50 * evZ + 0.12 * (epZ / dt);

        if (py > 0.11) {
          const gainX = Math.abs(evX) > 0.032 ? 0.50 : 0.20;
          const gainZ = Math.abs(evZ) > 0.032 ? 0.50 : 0.20;
          dwx = clamp(dwx + gainX * (evX / dt), -12, 12);
          dwz = clamp(dwz + gainZ * (evZ / dt), -12, 12);
          dwy = clamp(dwy + 0.12 * (evY / dt), -6, 6);

          if (thrustFilt > 0.25 && dirY > 0.7) {
            const actualTSpec = (ayKnown + dwy + 9.81 + drag * vy) / dirY;
            const kyMeas = actualTSpec / thrustFilt;
            if (kyMeas > 10 && kyMeas < 30) {
              kyEst += 0.03 * (kyMeas - kyEst);
              dwy *= 0.97;
            }
          }
        }
      }

      const drag = 0.42 / mEst;
      let tx, ty, tz, tvx = 0, tvy = 0, tvz = 0;
      let kpX = 6.5, kdX = 4.2, kpZ = 8.5, kdZ = 5.0, kpY = 7.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const g = obs.nextGate.centre;
        if (gateIdx !== obs.gateIndex) {
          gateIdx = obs.gateIndex;
          phase = 'align';
          settleCount = 0;
        }
        const errZ = Math.abs(g.z - pz);
        const errY = Math.abs(g.y - py);
        const tCross = Math.max(0.04, Math.min(0.25, (g.x - px) / Math.max(0.3, vx)));
        const zPredCross = pz + vz * tCross;
        const yPredCross = py + vy * tCross;

        if (phase === 'align') {
          tx = g.x - 0.25;
          ty = g.y;
          tz = g.z;
          if (px > g.x - 0.38 && errZ < 0.018 && errY < 0.06 && Math.abs(vz) < 0.08 && Math.abs(vy) < 0.20) {
            settleCount++;
          } else {
            settleCount = Math.max(0, settleCount - 1);
          }
          if (settleCount >= 6) {
            phase = 'cross';
          }
        }
        if (phase === 'cross') {
          // Safety check before crossing gate plane
          if (px < g.x - 0.03 && (Math.abs(zPredCross - g.z) > 0.025 || Math.abs(yPredCross - g.y) > 0.10)) {
            phase = 'align';
            settleCount = 0;
            tx = g.x - 0.25;
            ty = g.y;
            tz = g.z;
          } else {
            tx = g.x + 0.30;
            ty = g.y;
            tz = g.z;
            tvx = 0.9;
          }
        }
      } else {
        const pad = obs.pad.centre;
        tx = pad.x;
        tz = pad.z;
        const distH = Math.hypot(tx - px, tz - pz);
        const speedH = Math.hypot(vx, vz);
        if (phase !== 'descend') {
          ty = Math.max(0.35, Math.min(1.0, 0.25 + distH * 0.7));
          if (distH < 0.11 && speedH < 0.25 && py < 0.45) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          if (distH > 0.14) {
            ty = 0.22;
          } else {
            ty = 0.05;
            tvy = py > 0.14 ? -0.35 : -0.12;
          }
        }
      }

      const axDes = clamp(kpX * (tx - px) + kdX * (tvx - vx), -5.0, 5.0);
      const azDes = clamp(kpZ * (tz - pz) + kdZ * (tvz - vz), -5.5, 5.5);
      const ayDes = clamp(kpY * (ty - py) + kdY * (tvy - vy), -4.0, 5.0);

      const aThrustX = axDes + drag * vx - dwx;
      const aThrustZ = azDes + drag * vz - dwz;
      const aUp = Math.max(2.0, 9.81 + ayDes + drag * vy - dwy);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const aFwd = cy * aThrustX - sy * aThrustZ;
      const aRight = sy * aThrustX + cy * aThrustZ;

      let maxTilt = (obs.gateIndex === 3 && py < 0.16) ? 0.15 : 0.52;
      const pitchTarget = clamp(Math.atan2(aFwd, aUp), -maxTilt, maxTilt);
      const rollTarget = clamp(-Math.atan2(aRight, Math.hypot(aFwd, aUp)), -maxTilt, maxTilt);

      rollTrim = clamp(rollTrim + 0.35 * (rollTarget - att.roll) * dt, -0.25, 0.25);
      pitchTrim = clamp(pitchTrim + 0.35 * (pitchTarget - att.pitch) * dt, -0.25, 0.25);

      const rollCmd = clamp(rollTarget + 1.1 * (rollTarget - att.roll) - 0.12 * rates.roll + rollTrim, -0.6, 0.6);
      const pitchCmd = clamp(pitchTarget + 1.1 * (pitchTarget - att.pitch) - 0.12 * rates.pitch + pitchTrim, -0.6, 0.6);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      let thrustCmd = clamp((aUp / cosTilt) / kyEst, 0.0, 1.0);
      if (obs.gateIndex === 3 && phase === 'descend' && py <= 0.088 && Math.hypot( obs.pad.centre.x - px, obs.pad.centre.z - pz) < 0.12 && Math.hypot(vx, vy, vz) < 0.35) {
        thrustCmd = 0;
        return { thrust: 0, roll: 0, pitch: 0, yawRate: 0 };
      }

      thrustFilt += (thrustCmd - thrustFilt) * (1 - Math.exp(-dt / 0.04));
      yawTrim = clamp(yawTrim - 0.4 * att.yaw * dt, -0.8, 0.8);
      const yawRate = clamp(-2.5 * att.yaw - 0.3 * rates.yaw + yawTrim, -2, 2);

      return { thrust: thrustCmd, roll: rollCmd, pitch: pitchCmd, yawRate };
    },
  };
}

