    const p = knownParams;
    const lead = p.lag + 0.055;
    let wx = 0, wz = 0;
    const samples = 5;
    for (let i = 0; i < samples; i++) {
      const tau = t + (lead * i) / (samples - 1);
      let sx = p.baseWind.x, sz = p.baseWind.z;
      for (let j = 0; j < p.gusts.length; j++) {
