        tx = pad.x;
        tz = pad.z;
        const distH = Math.hypot(tx - px, tz - pz);
        const speedH = Math.hypot(vx, vz);
        const tiltMag = Math.max(Math.abs(att.roll), Math.abs(att.pitch));
        if (phase !== 'descend') {
          ty = clamp(0.18 + distH * 0.58, 0.18, 0.95);
