      const ayDes = clamp(kpY * (ty - py) + kdY * (tvy - vy), -4.0, 5.2);

      const aThrustX = axDes + drag * vx - dwx;
      const aThrustZ = azDes + drag * vz - dwz;
      const aUp = Math.max(2.5, 9.81 + ayDes + drag * vy - dwy);

